export default class DamageObject{constructor(i,t,s){this.position=i,this.size=t,this.damage=s,this.isDead=!1}checkCollision(i){return this.position.x<i.position.x+i.size.width&&this.position.x+this.size.width>i.position.x&&this.position.y<i.position.y+i.size.height&&this.position.y+this.size.height>i.position.y}draw(i){i.fillStyle="red",i.fillRect(this.position.x,this.position.y,this.size.width,this.size.height)}}